def min_trips(weights, limit):
    n = len(weights)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        for j in range(i):
            if j == 0:
                dp[i] = min(dp[i], dp[j] + 1)
            else:
                dp[i] = min(dp[i], dp[j] + 1 + (weights[i - 1] + weights[j - 1] <= limit))
                if j >= 2 and weights[i - 1] + weights[j - 1] + weights[j - 2] <= limit:
                    dp[i] = min(dp[i], dp[j - 1] + 1)
    return dp[n]

