import ipaddress
from typing import List, Dict, Union

def configure_devices(devices: List[Dict[str, Union[str, List[str]]]]) -> Dict[str, bool]:
    # Create a set to store unique primary IP addresses
    primary_ips = set()

    # Create a dictionary to store the result
    result = {}

    # Iterate over each device
    for device in devices:
        # Check if the primary IP address is already in use
        if device['primary_ip'] in primary_ips:
            # If it is, mark all devices with this IP address as False
            for d in devices:
                if d['primary_ip'] == device['primary_ip']:
                    result[d['name']] = False
            continue

        # Add the primary IP address to the set
        primary_ips.add(device['primary_ip'])

        # Create an IP address object for the primary IP
        primary_ip = ipaddress.ip_address(device['primary_ip'])

        # Initialize a flag to indicate if the primary IP is in any network
        in_network = False

        # Iterate over each network
        for network in device['networks']:
            # Create a network object from the CIDR notation
            net = ipaddress.ip_network(network, strict=False)

            # Check if the primary IP is in the network
            if primary_ip in net:
                # If it is, set the flag to True
                in_network = True
                break

        # Mark the device as True if its primary IP is in any network
        result[device['name']] = in_network

    return result

