        self.assertEqual(cycle_sort([3, 0, 2, 5, -1, 4, 1]), [-1, 0, 1, 2, 3, 4, 5])
        self.assertEqual(cycle_sort([10, 20, 1, 0]), [0, 1, 10, 20])

