def findMaxLengthSubarray(arr, N):
    # Create a hash map to store the frequency of each element
    freq_map = {}
    for num in arr:
        if num in freq_map:
            freq_map[num] += 1
        else:
            freq_map[num] = 1

    # Initialize variables to store the maximum length and the current window
    max_length = 0
    window_start = 0
    window_freq_map = {}

    # Iterate over the array
    for window_end in range(N):
        # Add the current element to the window frequency map
        num = arr[window_end]
        if num in window_freq_map:
            window_freq_map[num] += 1
        else:
            window_freq_map[num] = 1

        # Check if the current window has consecutive elements
        if is_consecutive(window_freq_map):
            max_length = max(max_length, window_end - window_start + 1)

        # Remove the leftmost element from the window frequency map
        num = arr[window_start]
        window_freq_map[num] -= 1
        if window_freq_map[num] == 0:
            del window_freq_map[num]
        window_start += 1

    return max_length

def is_consecutive(freq_map):
    keys = sorted(freq_map.keys())
    for i in range(len(keys) - 1):
        if keys[i + 1] - keys[i] != 1:
