from bisect import bisect_left

def longest_increasing_subsequence(A):
    if not A:
        return 0
    lis = []
    for num in A:
        pos = bisect_left(lis, num)
        if pos == len(lis):
            lis.append(num)
        else:
            lis[pos] = num
    return len(lis)

