def get_diagonal_elements(matrix_dict):
    # Initialize an empty dictionary to store the diagonal elements
    diagonal_dict = {}

    # Get the size of the matrix
    size = int(len(matrix_dict) ** 0.5)

    # Check if the matrix is square
    if size ** 2 != len(matrix_dict):
        return "Error: Input dictionary does not represent a square matrix."

    # Iterate over the keys in the input dictionary
    for key in matrix_dict:
        # Split the key into row and column indices
        row, col = map(int, key.split(','))

        # Check if the element is on the diagonal
        if row == col:
            # Add the element to the diagonal dictionary
            diagonal_dict[key] = matrix_dict[key]

    # Return the dictionary of diagonal elements
    return diagonal_dict

